// Supply names for controls generated by Unfold/Select2 outside Django labels.
(() => {
  function labelControls() {
    document.querySelectorAll('#result_list input[type="checkbox"]').forEach(input => {
      if (input.getAttribute('aria-label') || input.labels.length) return;
      const row = input.closest('tr');
      const cell = input.closest('td');
      const header = cell && document.querySelector(`#result_list thead th:nth-child(${cell.cellIndex + 1})`);
      const title = row && row.querySelector('th');
      input.setAttribute('aria-label', `${header?.textContent.trim() || 'Select'}: ${title?.textContent.trim() || input.value}`);
    });
    document.querySelectorAll('select.admin-autocomplete, select.unfold-filter-autocomplete').forEach(select => {
      const container = select.parentElement.querySelector('.select2-container');
      if (!container) return;
      const label = select.labels[0]?.textContent.trim() || select.getAttribute('aria-label') || select.name.replaceAll('__', ' ');
      container.querySelector('[role="combobox"]')?.setAttribute('aria-label', label);
      container.querySelector('.select2-search__field')?.setAttribute('aria-label', `Search ${label}`);
    });
    const open = document.querySelector('.select2-container [role="combobox"][aria-expanded="true"]');
    document.querySelectorAll('.select2-container--open .select2-search__field').forEach(input => {
      input.setAttribute('aria-label', `Search ${open?.getAttribute('aria-label') || 'options'}`);
    });
  }
  document.addEventListener('DOMContentLoaded', () => {
    setTimeout(labelControls, 0);
    if (window.django?.jQuery) django.jQuery(document).on('select2:open', labelControls);
    // Select2 can initialize twice during admin startup and replace its controls.
    new MutationObserver(records => {
      if (records.some(record => [...record.addedNodes].some(node => node.nodeType === 1 &&
          (node.matches('.select2-container') || node.querySelector('.select2-container'))))) labelControls();
    }).observe(document.body, {childList: true, subtree: true});
  });
  document.addEventListener('formset:added', () => setTimeout(labelControls, 0));
})();
